mapper.select:
WITH latest_reports AS MATERIALIZED ( SELECT DISTINCT ON ( swarm.userapps_id, swarm.user_downloader, swarm.torrent_id, swarm.peer_ip, swarm.peer_port ) swarm.userapps_id, swarm.user_downloader, swarm.torrent_id, swarm.peer_ip, swarm.peer_port, GREATEST(swarm.from_peer_traffic, 0)::numeric AS download_bytes, swarm.last_time_seen FROM public.swarm_tracker swarm WHERE swarm.last_time_seen >= #{startAt} AND swarm.last_time_seen < #{endAt} AND swarm.from_peer_traffic > 0
AND family(swarm.peer_ip) = #{ipVersion}
ORDER BY swarm.userapps_id, swarm.user_downloader, swarm.torrent_id, swarm.peer_ip, swarm.peer_port, swarm.last_time_seen DESC, swarm.id DESC ), grouped AS ( SELECT CASE family(latest.peer_ip) WHEN 4 THEN CASE WHEN #{ipv4Prefix} = 32 THEN host(latest.peer_ip) ELSE network(set_masklen(latest.peer_ip, #{ipv4Prefix}))::text END WHEN 6 THEN network(set_masklen(latest.peer_ip, #{ipv6Prefix}))::text END AS cidr, family(latest.peer_ip) AS ip_version, SUM(latest.download_bytes)::numeric AS download_bytes, COUNT(DISTINCT latest.userapps_id)::bigint AS reporter_count, COUNT(*)::bigint AS connection_count, COUNT(DISTINCT latest.torrent_id)::bigint AS torrent_count, MAX(latest.last_time_seen) AS latest_seen_at FROM latest_reports latest GROUP BY cidr, ip_version ) SELECT grouped.cidr::text AS cidr, grouped.ip_version, grouped.download_bytes::text AS download_bytes, grouped.reporter_count, grouped.connection_count, grouped.torrent_count, grouped.latest_seen_at, COUNT(*) OVER ()::bigint AS matching_groups FROM grouped WHERE grouped.download_bytes > #{thresholdBytes} ORDER BY grouped.download_bytes DESC, grouped.cidr LIMIT #{limit}
